// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** An outstanding receivable with the age of the debt (the Outstanding Patient Dues queue). */
export interface ReceivableQueueItemOut {
  ar_id: number;
  ar_type: "PatientCredit" | "Panel";
  patient_id: number | null;
  mrn: string | null;
  patient_name: string | null;
  mobile: string | null;
  panel_id: number | null;
  panel_name: string | null;
  invoice_id: number;
  invoice_no: string;
  amount_due: number;
  amount_paid: number;
  amount_written_off: number;
  balance: number;
  status: "Active" | "PartiallySettled" | "Settled" | "WrittenOff" | "Cancelled";
  due_date: string | null;
  created_at: string;
  days_overdue: number;
  /** "Overdue by N Days" or "Not yet due" */
  age_label: string;
}

/** Outstanding balances by age bucket (days since due) for one receivable type. */
export interface ReceivableAgingOut {
  ar_type: "PatientCredit" | "Panel";
  "0_30": number | null;
  "31_60": number | null;
  "61_90": number | null;
  "90_plus": number | null;
  total: number;
  items: number;
}

export interface SettleArIn {
  amount: number | string;
  method?: "Cash" | "Card" | "BankTransfer";
  reference_no?: string | null;
}

export interface ReceivableSettlementOut {
  payment: PaymentRecordOut;
  receivable: ReceivableOut;
}

/** A payment row with every reference (a receivable settlement returns it). */
export interface PaymentRecordOut {
  payment_id: number;
  receipt_no: string;
  payment_type: "Collection" | "Refund" | "WaiverDispensation" | "ARCollection";
  amount: number;
  method: "Cash" | "Card" | "BankTransfer" | "PanelCredit" | "PayrollDeduction" | "Charity";
  invoice_id: number | null;
  shift_id: number | null;
  collected_at: string;
  refund_disbursement_id: number | null;
  waiver_refund_order_id: number | null;
  ar_id: number | null;
  reference_no: string | null;
  collected_by: number;
  business_date: string;
  note: string | null;
}

export interface ReceivableOut {
  ar_id: number;
  ar_type: "PatientCredit" | "Panel";
  patient_id: number | null;
  panel_id: number | null;
  invoice_id: number;
  credit_request_id: number | null;
  amount_due: number;
  amount_paid: number;
  amount_written_off: number;
  status: "Active" | "PartiallySettled" | "Settled" | "WrittenOff" | "Cancelled";
  due_date: string | null;
  created_at: string;
  settled_at: string | null;
  row_version: number;
}

export interface WriteOffIn {
  amount: number | string;
  reason: string;
}

export interface CollectIn {
  /** Defaults to the full balance due */
  amount?: number | string | null;
  method?: "Cash" | "Card" | "BankTransfer";
  reference_no?: string | null;
}

export interface InvoicePaymentOut {
  payment: PaymentOut;
  invoice: InvoiceDetailOut;
}

