/** Outstanding Patient Dues queue (with age of debt) — GET /api/v1/finance/ar/outstanding (who may call: holders of finance.ar.view). */
export function arOutstanding(): Promise<ReceivableQueueItemOut[]> {
  return api<ReceivableQueueItemOut[]>("GET", `/finance/ar/outstanding`, undefined);
}

/** Receivables aging buckets — GET /api/v1/finance/ar/aging (who may call: holders of finance.ar.view). */
export function arAging(): Promise<ReceivableAgingOut[]> {
  return api<ReceivableAgingOut[]>("GET", `/finance/ar/aging`, undefined);
}

/** Settle Debt (patient returns to pay) — POST /api/v1/finance/ar/{ar_id}/settle (who may call: holders of finance.ar.collect). */
export function settleAr(ar_id: number, body: SettleArIn): Promise<ReceivableSettlementOut> {
  return api<ReceivableSettlementOut>("POST", `/finance/ar/${ar_id}/settle`, body, { idempotent: true });
}

/** Write off a receivable — POST /api/v1/finance/ar/{ar_id}/write-off (who may call: holders of finance.ar.write_off). */
export function writeOff(ar_id: number, body: WriteOffIn): Promise<ReceivableOut> {
  return api<ReceivableOut>("POST", `/finance/ar/${ar_id}/write-off`, body, { idempotent: true });
}

/** Collect a payment (lab / pharmacy / final IPD bill ...) — POST /api/v1/finance/invoices/{invoice_id}/payments (who may call: holders of finance.payment.collect). */
export function collectFinanceInvoicesPayments(invoice_id: number, body: CollectIn): Promise<InvoicePaymentOut> {
  return api<InvoicePaymentOut>("POST", `/finance/invoices/${invoice_id}/payments`, body, { idempotent: true });
}

/** Invoices (filters) — GET /api/v1/finance/invoices (who may call: holders of finance.invoice.view). */
export function listInvoices(query?: { patient_id?: number | null; status?: string | null; invoice_type?: string | null; limit?: number }): Promise<InvoiceListItemOut[]> {
  return api<InvoiceListItemOut[]>("GET", withQuery(`/finance/invoices`, query), undefined);
}

/** Invoice with lines and balance — GET /api/v1/finance/invoices/{invoice_id} (who may call: holders of finance.invoice.view). */
export function getInvoice(invoice_id: number): Promise<InvoiceDetailOut> {
  return api<InvoiceDetailOut>("GET", `/finance/invoices/${invoice_id}`, undefined);
}
